(()=>{
const root=document.querySelector('#app');const send=(type,data={})=>parent.postMessage({type,...data},location.origin==='null'?'*':location.origin);let reduced=false,geometryTall=false;
for(const [selector,label] of [['.spaces-entry','私密空间'],['.chat-settings-entry','设置'],['.spec-pagehead button','返回'],['.meme-toggle','选择表情'],['.voice-record-button','录制语音'],['.composer-row>.icon-button:first-child','更多工具']])for(const b of root.querySelectorAll(selector))if(!b.hasAttribute('aria-label'))b.setAttribute('aria-label',label);
for(const overlay of root.querySelectorAll('.spec-overlay,.v13-sheet-overlay')){overlay.setAttribute('role','dialog');const heading=overlay.querySelector('h2');if(heading)overlay.setAttribute('aria-label',heading.textContent);root.querySelector('.chat-shell')?.setAttribute('inert','');}
const motion={frame:0,width:0,velocity:0,target:0,started:0,from:0,initialVelocity:0};let shell;
function toast(text){document.querySelector('.review-toast')?.remove();const p=document.createElement('p');p.className='review-toast';p.textContent=text;document.body.append(p);setTimeout(()=>p.remove(),2600);send('notice',{text})}
function stopMotion(){cancelAnimationFrame(motion.frame);motion.frame=0}
function paint(now){const dt=240,t=Math.min(1,(now-motion.started)/dt),t2=t*t,t3=t2*t;const a=2*t3-3*t2+1,b=t3-2*t2+t,c=-2*t3+3*t2;motion.width=a*motion.from+b*dt*motion.initialVelocity+c*motion.target;motion.velocity=((6*t2-6*t)*motion.from+(3*t2-4*t+1)*dt*motion.initialVelocity+(-6*t2+6*t)*motion.target)/dt;const scale=motion.width/motion.target;shell.style.transform=`scaleX(${scale})`;for(const layer of shell.children)layer.style.transform=`scaleX(${1/scale})`;if(t<1)motion.frame=requestAnimationFrame(paint);else{shell.style.transform='none';for(const layer of shell.children)layer.style.transform='none';motion.frame=0;motion.velocity=0;}}
function changeState(f){const old=root.querySelector('.v13-state-media');if(!old)return;const parsed=new DOMParser().parseFromString(f.html,'text/html');const next=parsed.querySelector('.v13-state-media');const card=root.querySelector('.v13-state-card');card.querySelector('h2').innerHTML=parsed.querySelector('h2').innerHTML;card.querySelector(':scope>p').textContent=parsed.querySelector('.v13-state-card>p').textContent;
const glyph=old.querySelector(':scope>svg,:scope>.v13-play');glyph?.remove();const newGlyph=next.querySelector(':scope>svg,:scope>.v13-play');if(newGlyph)old.prepend(newGlyph.cloneNode(true));old.className=next.className;root.dataset.reviewName=f.name;
const badge=next.querySelector('.v13-state-status,.v13-state-meta');if(!badge){shell?.remove();shell=null;return;}
// Measure the target once. Per-frame updates only transform the anchored shell
// and compensate its text; the card's dimensions are never animated by layout.
const temp=badge.cloneNode(true);temp.style.visibility='hidden';old.append(temp);const width=temp.getBoundingClientRect().width;const computed=getComputedStyle(temp);const bg=computed.backgroundColor,color=computed.color;const children=temp.innerHTML;const cls=temp.className;temp.remove();
if(!shell){shell=old.querySelector('.v13-state-status,.v13-state-meta');if(shell){motion.width=shell.getBoundingClientRect().width;shell.replaceChildren(Object.assign(document.createElement('div'),{innerHTML:shell.innerHTML}));}else{shell=document.createElement('div');old.append(shell);motion.width=width;}}
const fromWidth=shell.getBoundingClientRect().width;const fromBg=getComputedStyle(shell).backgroundColor;const fromColor=getComputedStyle(shell).color;stopMotion();for(const animation of shell.getAnimations())animation.cancel();
// Freeze visible inner layers when a change interrupts an earlier fade.
const frozen=document.createElement('div');frozen.setAttribute('aria-hidden','true');frozen.inert=true;for(const child of [...shell.children]){const clone=child.cloneNode(true);clone.style.opacity=getComputedStyle(child).opacity;clone.style.transform='none';frozen.append(clone);}shell.replaceChildren();
shell.className=cls+' review-capsule';shell.style.cssText=`position:absolute;right:7px;bottom:7px;width:${width}px;height:32px;min-height:32px;padding:0;border-radius:16px;transform-origin:right center;background:${bg};color:${color};overflow:visible;display:block;`;
const layer=document.createElement('div');layer.innerHTML=children;for(const x of [frozen,layer]){x.style.cssText='position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:8px;padding:0 10px;transform-origin:center;white-space:nowrap;';shell.append(x)}
if(reduced){frozen.remove();motion.width=width;motion.velocity=0;return;}
frozen.animate([{opacity:1},{opacity:0}],{duration:180,easing:'cubic-bezier(.33,0,.67,1)',fill:'forwards'}).finished.then(()=>frozen.remove()).catch(()=>{});layer.animate([{opacity:0},{opacity:1}],{duration:180,easing:'cubic-bezier(.33,0,.67,1)',fill:'both'});shell.animate([{backgroundColor:fromBg,color:fromColor},{backgroundColor:bg,color}],{duration:180,fill:'both'});
motion.from=fromWidth;motion.target=width;motion.initialVelocity=motion.velocity;motion.started=performance.now();paint(motion.started);
}
function mediaActions(){document.querySelector('.review-action-panel')?.remove();const panel=document.createElement('section');panel.className='review-action-panel';panel.setAttribute('role','dialog');panel.setAttribute('aria-label','未发送媒体操作');panel.innerHTML='<button data-retry>重试上传</button><button data-remove>移除未发送媒体</button><button data-cancel>取消</button>';panel.onclick=e=>{const b=e.target.closest('button');if(!b)return;panel.remove();if(b.hasAttribute('data-retry'))send('navigate',{id:'state-P02'});if(b.hasAttribute('data-remove')){root.querySelector('.v13-state-media')?.remove();toast('已移除未发送媒体（原型示例）')}};document.body.append(panel);}
const geometryMotion={frame:0,height:128,velocity:0,from:128,target:128,initialVelocity:0,started:0,element:null,background:null,note:null,originalBackground:'',originalOverflow:''};
function finishGeometry(){const g=geometryMotion,e=g.element;if(!e)return;cancelAnimationFrame(g.frame);g.frame=0;g.height=g.target;g.velocity=0;e.style.height=g.target+'px';e.style.background=g.originalBackground;e.style.overflow=g.originalOverflow;g.background?.remove();g.background=null;for(const child of e.children)child.style.translate='';if(g.note)g.note.style.translate='';}
function paintGeometry(now){const g=geometryMotion,e=g.element;if(!e?.isConnected){finishGeometry();return;}const dt=280,t=Math.min(1,(now-g.started)/dt),t2=t*t,t3=t2*t;g.height=(2*t3-3*t2+1)*g.from+(t3-2*t2+t)*dt*g.initialVelocity+(-2*t3+3*t2)*g.target;g.velocity=((6*t2-6*t)*g.from+(3*t2-4*t+1)*dt*g.initialVelocity+(-6*t2+6*t)*g.target)/dt;const scale=g.height/g.target;g.background.style.transform=`scaleY(${scale})`;g.background.style.borderRadius=`18px / ${18/scale}px`;for(const child of e.children){if(child===g.background)continue;child.style.translate=`0 ${(child.matches('svg,.v13-play')?.5:1)*(g.height-g.target)}px`;}if(g.note)g.note.style.translate=`0 ${g.height-g.target}px`;if(t<1)g.frame=requestAnimationFrame(paintGeometry);else finishGeometry();}
function geometry(){const e=root.querySelector('.v13-state-media');if(!e)return;const g=geometryMotion;if(g.element!==e){finishGeometry();g.element=e;g.height=e.getBoundingClientRect().height;g.velocity=0;}cancelAnimationFrame(g.frame);g.frame=0;geometryTall=!geometryTall;g.from=g.height;g.target=geometryTall?192:128;g.initialVelocity=g.velocity;g.started=performance.now();g.note=e.nextElementSibling;if(!g.background){const s=getComputedStyle(e);g.originalBackground=e.style.background;g.originalOverflow=e.style.overflow;g.background=document.createElement('div');g.background.setAttribute('aria-hidden','true');g.background.style.cssText=`position:absolute;inset:0;pointer-events:none;transform-origin:top center;background:${s.background};`;e.prepend(g.background);e.style.background='transparent';e.style.overflow='visible';}e.style.height=g.target+'px';if(reduced){finishGeometry();return;}paintGeometry(g.started);}
// A single position owner drives the menu group or the paired pages.
const demo={x:0,v:0,to:0,from:0,v0:0,time:0,frame:0,duration:240};
function paintDemo(x){const menu=root.querySelector('.review-menu-group');if(menu){menu.style.transform=`translateY(${-180*x}px)`;for(const e of root.querySelectorAll('.spec-reactions,.spec-message-menu,.review-menu-dim')){e.style.opacity=x;e.style.pointerEvents=x>.99?'auto':'none';}}else{const old=root.querySelector('.review-page-old'),next=root.querySelector('.review-page-new');if(old)old.style.transform=`translateX(${-18*x}%)`;if(next)next.style.transform=`translateX(${100*(1-x)}%)`;}}
function demoTick(now){const t=Math.min(1,(now-demo.time)/demo.duration),t2=t*t,t3=t2*t;demo.x=(2*t3-3*t2+1)*demo.from+(t3-2*t2+t)*demo.duration*demo.v0+(-2*t3+3*t2)*demo.to;demo.v=((6*t2-6*t)*demo.from+(3*t2-4*t+1)*demo.duration*demo.v0+(-6*t2+6*t)*demo.to)/demo.duration;paintDemo(demo.x);if(t<1)demo.frame=requestAnimationFrame(demoTick);else{demo.frame=0;demo.v=0;}}
function toggleDemo(){cancelAnimationFrame(demo.frame);demo.to=demo.to?0:1;if(reduced){demo.x=demo.to;demo.v=0;paintDemo(demo.x);return;}demo.from=demo.x;demo.v0=demo.v;demo.time=performance.now();demo.duration=root.querySelector('.review-menu-group')?240:280;demoTick(demo.time);}
window.addEventListener('message',e=>{if(e.source!==parent)return;const d=e.data;if(d.type==='media-state')changeState(d.fixture);if(d.type==='geometry')geometry();if(d.type==='demo-motion')toggleDemo();if(d.type==='reduce'){reduced=d.value;document.querySelectorAll('.v13-state-ring').forEach(r=>r.style.animationPlayState=reduced?'paused':'running');if(reduced){finishGeometry();cancelAnimationFrame(demo.frame);demo.frame=0;demo.x=demo.to;demo.v=0;paintDemo(demo.x);stopMotion();shell?.getAnimations().forEach(a=>a.finish());if(shell){shell.style.transform='none';for(const layer of shell.children){layer.style.transform='none';layer.getAnimations().forEach(a=>a.finish());}}}}});
let held=0;root.addEventListener('pointerdown',e=>{if(e.target.closest('.v13-state-media.failed'))held=setTimeout(mediaActions,500)});for(const event of ['pointerup','pointercancel','pointermove'])root.addEventListener(event,()=>clearTimeout(held));root.addEventListener('contextmenu',e=>{if(e.target.closest('.v13-state-media.failed')){e.preventDefault();mediaActions()}});
document.addEventListener('submit',e=>e.preventDefault());
root.addEventListener('click',e=>{const b=e.target.closest('button,[role=button]');if(!b)return;const txt=(b.textContent||b.getAttribute('aria-label')||'').trim();
if(b.matches('.spaces-entry')){send('navigate',{id:'spaces'});return;}if(b.matches('.chat-settings-entry')){send('navigate',{id:'settings'});return;}
if(b.closest('.v13-state-media')){if(b.classList.contains('v13-state-retry'))send('navigate',{id:root.dataset.reviewName==='state-R01'?'state-P02':'state-R04'});else if(root.dataset.reviewName==='state-R07')send('navigate',{id:'state-R08'});return;}
const routes=[[/新建空间/,'nameform'],[/选择头像|更换头像/,'avatar'],[/使用表情|使用图片/,'nameform'],[/消息信息/,'message-info'],[/设置/,'settings'],[/恢复/,'restore'],[/邀请/,'invite'],[/复制/,'invite'],[/取消|关闭|知道了|返回|完成/,'chat-blue-light']];
if(/验证|检查备份|确认/.test(txt)){const note=root.querySelector('.v13-field-note.error');if(note)note.textContent='原型示例：请检查后重试，内容会保留。';else toast('已体验操作反馈（未执行真实业务）');return;}
if(/复制/.test(txt)){toast('邀请链接已复制（原型示例）');return;}
for(const [test,id] of routes)if(test.test(txt)){send('navigate',{id});return;}
if(b.matches('[aria-pressed]')){b.setAttribute('aria-pressed',String(b.getAttribute('aria-pressed')!=='true'));return;}
if(b.matches('[role=switch]')){b.setAttribute('aria-checked',String(b.getAttribute('aria-checked')!=='true'));return;}
if(b.matches('[role=tab]')){b.parentElement.querySelectorAll('[role=tab]').forEach(n=>n.setAttribute('aria-selected',String(n===b)));return;}
toast('此处仅体验视觉状态，不执行真实业务。');});
send('ready');
})();
